/*
 * Tier A — 15 methods, scalars only.
 *
 * Both directions are asserted for every one of them: the example frame parses,
 * and each of its systematically broken variants is REJECTED. The negatives are
 * generated by `malformed.ts`, so the count follows the surface area rather
 * than a hand-written list somebody forgets to extend.
 *
 * Then the four rules a generated battery cannot state: the enum arguments are
 * closed, a Java byte has a range, an `FSkinProp` has a shape, and the three
 * blocking methods are the only Tier A frames that carry a `callId`.
 */

import { describe, expect, it } from 'vitest';

import { CLIENT_FRAME_EXAMPLES, SERVER_FRAME_EXAMPLES } from './examples.ts';
import { malformedTable } from './malformed.ts';
import { safeParseClientFrame, safeParseServerFrame } from './envelope.ts';
import {
  TIER_A_METHODS,
  UseManaSchema,
  NextGameDecisionActionSchema,
  ShowOptionDialogSchema,
} from './tier-a.ts';

const TIER_A = new Set<string>(TIER_A_METHODS);

const serverExamples = Object.fromEntries(
  Object.entries(SERVER_FRAME_EXAMPLES).filter(([method]) => TIER_A.has(method)),
);
const clientExamples = Object.fromEntries(
  Object.entries(CLIENT_FRAME_EXAMPLES).filter(([method]) => TIER_A.has(method)),
);

describe('Tier A — the 15 scalar-only methods', () => {
  it('models exactly 15 methods, 9 server and 6 client', () => {
    expect(TIER_A_METHODS).toHaveLength(15);
    expect(Object.keys(serverExamples)).toHaveLength(9);
    expect(Object.keys(clientExamples)).toHaveLength(6);
  });

  it.each(Object.keys(serverExamples))('%s parses as a server frame', (method) => {
    const result = safeParseServerFrame(serverExamples[method]);
    expect(result.ok ? null : result.errors).toBeNull();
  });

  it.each(Object.keys(clientExamples))('%s parses as a client frame', (method) => {
    const result = safeParseClientFrame(clientExamples[method]);
    expect(result.ok ? null : result.errors).toBeNull();
  });

  it.each(malformedTable(serverExamples))(
    'rejects a server $method with $label',
    ({ input }) => {
      expect(safeParseServerFrame(input).ok).toBe(false);
    },
  );

  it.each(malformedTable(clientExamples))(
    'rejects a client $method with $label',
    ({ input }) => {
      expect(safeParseClientFrame(input).ok).toBe(false);
    },
  );
});

describe('Tier A — the rules a generated battery cannot state', () => {
  it('nextGameDecision takes Forge’s three constants and nothing else', () => {
    for (const decision of ['NEW', 'CONTINUE', 'QUIT']) {
      expect(
        NextGameDecisionActionSchema.safeParse({
          kind: 'act',
          method: 'nextGameDecision',
          decision,
        }).success,
      ).toBe(true);
    }
    for (const decision of ['MAYBE', 'new', '', 'RESTART']) {
      expect(
        NextGameDecisionActionSchema.safeParse({
          kind: 'act',
          method: 'nextGameDecision',
          decision,
        }).success,
      ).toBe(false);
    }
  });

  it('useMana carries a signed Java byte, and only a byte', () => {
    const act = (color: unknown) =>
      UseManaSchema.safeParse({ kind: 'act', method: 'useMana', color }).success;
    expect(act(0)).toBe(true);
    expect(act(127)).toBe(true);
    expect(act(-128)).toBe(true);
    expect(act(128)).toBe(false);
    expect(act(-129)).toBe(false);
    expect(act(1.5)).toBe(false);
  });

  it('an FSkinProp is an enum constant name or null, not free text', () => {
    const withIcon = (icon: unknown) =>
      ShowOptionDialogSchema.safeParse({
        ...(SERVER_FRAME_EXAMPLES.showOptionDialog as Record<string, unknown>),
        icon,
      }).success;
    expect(withIcon('ICO_QUESTION')).toBe(true);
    expect(withIcon(null)).toBe(true);
    expect(withIcon('ico_question')).toBe(false);
    expect(withIcon('')).toBe(false);
    expect(withIcon('Not A Constant')).toBe(false);
  });

  it('only the three blocking methods carry a callId', () => {
    const blocking = ['showConfirmDialog', 'showOptionDialog', 'showInputDialog'];
    for (const [method, frame] of Object.entries(serverExamples)) {
      const record = frame as Record<string, unknown>;
      expect([method, 'callId' in record]).toEqual([method, blocking.includes(method)]);
      expect([method, record.kind]).toEqual([method, blocking.includes(method) ? 'ask' : 'notify']);
    }
  });

  it('a fire-and-forget method cannot be sent as an ask', () => {
    expect(
      safeParseServerFrame({
        kind: 'ask',
        callId: 'c-99',
        method: 'message',
        message: 'hi',
        title: 'Forge',
      }).ok,
    ).toBe(false);
  });
});
